import{_ as o,o as t,c as n,a5 as i}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"3.2.6 OTP Verification","description":"","frontmatter":{},"headers":[],"relativePath":"feature/authentication/3-2-6-otp-verification/spec.md","filePath":"feature/authentication/3-2-6-otp-verification/spec.md"}'),a={name:"feature/authentication/3-2-6-otp-verification/spec.md"};function r(d,e,s,c,l,h){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="_3-2-6-otp-verification" tabindex="-1">3.2.6 OTP Verification <a class="header-anchor" href="#_3-2-6-otp-verification" aria-label="Permalink to &quot;3.2.6 OTP Verification&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>FR Code</td><td>3.2.6</td></tr><tr><td>Feature</td><td>OTP Verification (phone-linking primitive)</td></tr><tr><td>Domain</td><td>Authentication (FR 3.2)</td></tr><tr><td>Role</td><td>Any signed-in user linking a phone number to their account</td></tr><tr><td>Version</td><td>2.0 — 2026-09-25 — refocused on phone-linking OTP as the primary subject</td></tr><tr><td>Document status</td><td>Implemented</td></tr></tbody></table><h2 id="function-trigger" tabindex="-1">Function Trigger <a class="header-anchor" href="#function-trigger" aria-label="Permalink to &quot;Function Trigger&quot;">​</a></h2><p>Begins when a signed-in user opens &quot;Link phone&quot; on their profile, enters a phone number, and then enters the six-digit code they receive.</p><p><strong>Scope note:</strong> OTP Verification is a general one-time-code mechanism reused by two concrete flows in the codebase: (1) email verification at sign-up (<code>POST /verify-otp</code> + <code>POST /resend-otp</code>, owned by FR 3.2.1 — the sibling flow, mentioned here only for contrast) and (2) <strong>phone linking</strong>, <code>POST /api/v1/auth/link/phone</code> + <code>POST /api/v1/auth/verify-phone-otp</code>, which is the primary subject of this FR because it is the other concrete OTP-code-driven endpoint pair in the codebase. FR 3.2.9 (Deactivate Account) also reuses this same numeric-OTP pattern via <code>POST /deactivate/send-otp</code>, noted briefly below as a third reuse site, not detailed here.</p><h2 id="function-description" tabindex="-1">Function Description <a class="header-anchor" href="#function-description" aria-label="Permalink to &quot;Function Description&quot;">​</a></h2><ul><li><strong>Actors / Roles:</strong> A signed-in user (Bearer token required) linking a phone number to their account.</li><li><strong>Purpose:</strong> Confirm ownership of a phone number with a short-lived one-time code before attaching it to the account.</li><li><strong>Interface:</strong> A &quot;Link phone&quot; modal on the Profile page (<code>LinkPhoneModal.tsx</code>) — not a standalone screen — with two steps: a phone number input, then a six-digit code input.</li><li><strong>Data Processing:</strong> <code>AuthController.linkPhone</code> / <code>AuthController.verifyPhoneOtp</code> delegate to <code>AuthServiceImpl</code>. The service normalizes the phone number, generates a 6-digit numeric code, stores <code>code:phone</code> together in Redis with a 10-minute TTL, enforces a 60-second resend cooldown and a 5-attempt wrong-code limit, and on success sets <code>user.phone</code>.</li><li><strong>⚠ BA conflict — delivery channel:</strong> <code>AuthServiceImpl.linkPhone</code> sends the code via <code>mailService.sendOtpEmail</code> (the user&#39;s account <strong>email</strong>), not via SMS. Phone-ownership verification delivered by email rather than by a text message to the phone itself is an unusual pairing and likely a BA/code mismatch — flagged for BA review, not silently normalized away here.</li></ul><h2 id="screen-layout" tabindex="-1">Screen Layout <a class="header-anchor" href="#screen-layout" aria-label="Permalink to &quot;Screen Layout&quot;">​</a></h2><p>Figure — Link Phone modal (Profile page, <code>LinkPhoneModal.tsx</code>):</p><ul><li>Rendered as a centered modal overlay on the Profile page (<code>fixed inset-0</code> dialog), not a dedicated route.</li><li>Step <code>&quot;phone&quot;</code>: a phone number <code>Input</code> plus Cancel / &quot;Send OTP&quot; buttons; &quot;Send OTP&quot; is disabled while empty or sending.</li><li>Step <code>&quot;otp&quot;</code>: a hint line plus a six-digit code <code>Input</code>, plus Cancel / &quot;Verify&quot; buttons; &quot;Verify&quot; is disabled while empty or verifying.</li><li>On send success: toast <code>profile.linkPhone.otpSent</code>, advances to the <code>&quot;otp&quot;</code> step.</li><li>On verify success: toast <code>profile.linkPhone.verifySuccess</code>, calls <code>onLinked(phone)</code>, closes and resets the modal.</li><li>On any error: toast built from <code>extractErrorMessage</code>, falling back to <code>profile.linkPhone.sendError</code> / <code>profile.linkPhone.verifyError</code>.</li></ul><h2 id="function-details" tabindex="-1">Function Details <a class="header-anchor" href="#function-details" aria-label="Permalink to &quot;Function Details&quot;">​</a></h2><h3 id="data-specifications" tabindex="-1">Data Specifications <a class="header-anchor" href="#data-specifications" aria-label="Permalink to &quot;Data Specifications&quot;">​</a></h3><ul><li><strong>Input required:</strong> <code>phone</code> (link step, body <code>LinkPhoneRequest</code>); <code>otpCode</code> (verify step, body <code>VerifyPhoneOtpRequest</code>). Both endpoints additionally require a valid <code>Authorization: Bearer &lt;accessToken&gt;</code> header.</li><li><strong>Input optional:</strong> none.</li><li><strong>System data:</strong> <code>userId</code> (resolved from the access token), Redis key <code>phone:otp:{userId}</code> → value <code>&quot;{otp}:{phone}&quot;</code> (TTL 10 min), <code>phone:otp:resend:{userId}</code> (cooldown marker, TTL 60s), <code>phone:otp:attempt:{userId}</code> (wrong-attempt counter, TTL 10 min), <code>user.phone</code>.</li><li><strong>Output:</strong> <code>ApiResponse&lt;Void&gt;</code> — 200 with no data on both endpoints.</li></ul><h3 id="business-rules" tabindex="-1">Business Rules <a class="header-anchor" href="#business-rules" aria-label="Permalink to &quot;Business Rules&quot;">​</a></h3><ul><li><strong>BR-03</strong> <em>(reused from the email-OTP primitive, FR 3.2.1):</em> numeric OTP is 6 digits, TTL 10 minutes, single-use, cleared on success — the same shape <code>AuthServiceImpl.linkPhone</code>/<code>verifyPhoneOtp</code> apply to the phone code, even though delivery here is by email rather than SMS.</li><li><strong>BR-04</strong> <em>(reused):</em> OTP resend/reissue has a 60-second cooldown, here scoped per <code>userId</code> (<code>phone:otp:resend:{userId}</code>) rather than per email address.</li><li><strong>BR-07</strong> <em>(phone-linking specific, built on BR-03/BR-04):</em><ul><li><code>phone</code> fails <code>PhoneUtil.normalize</code> (not a valid E.164 number) → 400 <code>INVALID_PHONE</code>.</li><li>Caller&#39;s user record not found → 404 <code>USER_NOT_FOUND</code>.</li><li><code>phone</code> already in use by a <strong>different</strong> user → 409 <code>PHONE_ALREADY_IN_USE</code>.</li><li>A repeat <code>link/phone</code> call while <code>phone:otp:resend:{userId}</code> is still set → 429 <code>RATE_LIMIT_EXCEEDED</code>; the pending code is <strong>not</strong> replaced.</li><li>On an accepted <code>link/phone</code> call: generates a new 6-digit code, writes <code>phone:otp:{userId}</code> = <code>&quot;{otp}:{phone}&quot;</code> (TTL 10 min), sets the 60s resend cooldown, clears <code>phone:otp:attempt:{userId}</code>, and sends the code by email.</li><li><code>verify-phone-otp</code> with no <code>phone:otp:{userId}</code> key (never requested or expired) → 400 <code>OTP_INVALID</code>.</li><li>Wrong code → increments <code>phone:otp:attempt:{userId}</code> (TTL 10 min); on the 5th wrong attempt both <code>phone:otp:{userId}</code> and the attempt key are deleted and the answer is 400 <code>OTP_TOO_MANY_ATTEMPTS</code>; below 5 attempts, 400 <code>OTP_INVALID</code>.</li><li>Correct code: deletes both Redis keys, <strong>re-checks</strong> phone uniqueness (race-condition guard against a concurrent link by another user) → 409 <code>PHONE_ALREADY_IN_USE</code> if now taken; reloads the user (404 <code>USER_NOT_FOUND</code> if gone) and sets <code>user.phone</code>.</li></ul></li><li>Auth guard on both endpoints: missing/invalid Bearer token → 401 <code>INVALID_CREDENTIALS</code> (thrown by <code>requireUserId</code> in <code>AuthController</code>, before the service is even called).</li></ul><h3 id="validation" tabindex="-1">Validation <a class="header-anchor" href="#validation" aria-label="Permalink to &quot;Validation&quot;">​</a></h3><ul><li><code>phone</code> empty or fails <code>PhoneUtil.normalize</code> → Display: MSG02.</li><li><code>otpCode</code> empty → Display: MSG02.</li><li><code>otpCode</code> invalid or expired → Display: MSG20.</li></ul><h2 id="functionalities" tabindex="-1">Functionalities <a class="header-anchor" href="#functionalities" aria-label="Permalink to &quot;Functionalities&quot;">​</a></h2><h3 id="normal-flow" tabindex="-1">Normal Flow <a class="header-anchor" href="#normal-flow" aria-label="Permalink to &quot;Normal Flow&quot;">​</a></h3><ol><li>Signed-in user opens the &quot;Link phone&quot; modal from the Profile page and enters a phone number.</li><li>Client calls <code>POST /api/v1/auth/link/phone { phone }</code> with the Bearer token.</li><li>System normalizes the phone number, checks it is not already in use by another user, generates a 6-digit code, stores it with the phone number in Redis (TTL 10 min), starts the 60s resend cooldown, and emails the code. Toast <code>profile.linkPhone.otpSent</code>.</li><li>User enters the code in the modal&#39;s second step.</li><li>Client calls <code>POST /api/v1/auth/verify-phone-otp { otpCode }</code> with the Bearer token.</li><li>System matches the code, clears the pending code and attempt counter, re-checks phone uniqueness, and sets <code>user.phone</code>. Toast <code>profile.linkPhone.verifySuccess</code>; modal closes.</li></ol><h3 id="abnormal-cases" tabindex="-1">Abnormal Cases <a class="header-anchor" href="#abnormal-cases" aria-label="Permalink to &quot;Abnormal Cases&quot;">​</a></h3><ul><li>2.a1: <code>phone</code> fails normalization → 400 <code>INVALID_PHONE</code>, Display: MSG02. 2.a2: User corrects the phone number and resubmits.</li><li>2.b1: Phone already used by another user → 409 <code>PHONE_ALREADY_IN_USE</code>, toast <code>profile.linkPhone.sendError</code>. 2.b2: User enters a different phone number.</li><li>2.c1: <code>link/phone</code> called again inside the 60s cooldown → 429 <code>RATE_LIMIT_EXCEEDED</code>, toast <code>profile.linkPhone.sendError</code> (no dedicated MSG88 wiring observed on this endpoint&#39;s FE handler — see BA conflict below). 2.c2: User waits for the cooldown to elapse.</li><li>5.a1: No pending code (never requested or expired) → 400 <code>OTP_INVALID</code>, Display: MSG20. 5.a2: User goes back to step 1 and requests a new code.</li><li>5.b1: Wrong code, below 5 attempts → 400 <code>OTP_INVALID</code>, Display: MSG20. 5.b2: User re-enters the code.</li><li>5.c1: 5th wrong attempt → 400 <code>OTP_TOO_MANY_ATTEMPTS</code>, Display: MSG20; the pending code is discarded. 5.c2: User must restart from step 1 (<code>link/phone</code>) to get a new code.</li><li>5.d1: Correct code, but the phone was taken by another user in the meantime (race) → 409 <code>PHONE_ALREADY_IN_USE</code>, toast <code>profile.linkPhone.verifyError</code>. 5.d2: User enters a different phone number and restarts.</li><li>5.e1: User record disappears between link and verify → 404 <code>USER_NOT_FOUND</code>, toast <code>profile.linkPhone.verifyError</code>.</li><li>Missing/expired Bearer token on either call → 401 <code>INVALID_CREDENTIALS</code>; user is redirected to sign in.</li></ul><h2 id="post-conditions" tabindex="-1">Post-Conditions <a class="header-anchor" href="#post-conditions" aria-label="Permalink to &quot;Post-Conditions&quot;">​</a></h2><ul><li>On success: <code>user.phone</code> is set to the normalized number; <code>phone:otp:{userId}</code> and <code>phone:otp:attempt:{userId}</code> are cleared.</li><li>On failure: no change to <code>user.phone</code>; Redis state reflects the specific failure path (cooldown key persists on 429; both keys are deleted on the 5th wrong attempt).</li></ul><h2 id="ba-conflicts-flagged" tabindex="-1">BA Conflicts Flagged <a class="header-anchor" href="#ba-conflicts-flagged" aria-label="Permalink to &quot;BA Conflicts Flagged&quot;">​</a></h2><ol><li><strong>Delivery channel mismatch:</strong> phone-ownership verification is delivered by email (<code>mailService.sendOtpEmail</code>), not SMS. A phone number is never actually contacted during this flow — flag for BA to confirm this is intentional (e.g. cost/vendor reasons) rather than an oversight.</li><li><strong>No dedicated success message:</strong> the appendix (Section5_Requirement_Appendix.md) has no MSG code for &quot;phone linked successfully.&quot; MSG26 (&quot;Profile updated successfully&quot;) is generic and not phone-specific; MSG21&#39;s copy is hardcoded to &quot;...has been sent to {email_address},&quot; which reads oddly if reused for a phone-linking resend confirmation. The FE modal instead uses local i18n keys (<code>profile.linkPhone.otpSent</code>, <code>profile.linkPhone.verifySuccess</code>) that are not backed by any MSGxx code in the appendix — recommend BA either register a new MSG or accept these as out-of-appendix UI copy.</li><li><strong>MSG88 (resend cooldown) wiring unconfirmed on this endpoint:</strong> the appendix defines MSG88 for &quot;resend OTP in cooldown,&quot; matching BR-04 semantics, but <code>LinkPhoneModal.tsx</code>&#39;s error path uses a generic <code>extractErrorMessage</code> fallback (<code>profile.linkPhone.sendError</code>) rather than a specific MSG88 toast — worth confirming with FE whether the 429 response is mapped to MSG88 text anywhere upstream.</li></ol><h2 id="out-of-scope" tabindex="-1">Out of Scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of Scope&quot;">​</a></h2><ul><li>Email OTP verification at sign-up (<code>verify-otp</code> / <code>resend-otp</code>) — owned by FR 3.2.1, mentioned above only as the sibling flow this mechanism is shared with.</li><li>Deactivate-account OTP (<code>deactivate/send-otp</code>) — owned by FR 3.2.9; it reuses the same 6-digit/10-minute/60s-cooldown pattern but is not detailed here.</li><li>Two-Factor Authentication (TOTP) — FR 3.2.7, a different mechanism entirely (no email/SMS code).</li><li>Unlinking a phone number (<code>unlink/phone</code>) — no OTP involved, out of scope.</li></ul><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><p><a href="./../../../../../FormReportDA/report_drafts/Section5_Requirement_Appendix.html">Section5_Requirement_Appendix.md</a></p>',30)])])}const m=o(a,[["render",r]]);export{u as __pageData,m as default};
